export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  let attempt = 0;
  let issue = null;

  while (issue === null && attempt < 3) {
    attempt += 1;
    try {
      const fetched = await tools.jira.getIssue({ key: input.issueKey });
      issue = fetched;
    } catch (error) {
      // Issue service is flaky — fall through to the next attempt.
    }
  }

  if (issue === null) {
    await tools.slack.send({
      channel: "#ops",
      message: `Could not fetch Jira issue ${input.issueKey} after ${attempt} attempts. Giving up.`
    });
    return { fetched: false };
  }

  await tools.jira.transitionIssue({ key: input.issueKey, status: "In Review" });

  return { fetched: true, issue };
}

import type { Tools } from "../generated/tools";
import { formatDigest } from "@flows/lib";

export default async function flow(
  input: { repository: string; jql: string; recipient: string },
  tools: Tools
) {
  const [stats, issues, activity] = await Promise.all([
    tools.github.getRepoStats({ repo: input.repository }),
    tools.jira.searchIssues({ jql: input.jql }),
    tools.slack.getChannelActivity({ channel: "#engineering" }),
  ]);

  const digest = formatDigest(stats, issues, activity);

  await tools.email.send({
    to: input.recipient,
    subject: `Weekly digest — ${input.repository}`,
    body: digest,
  });

  return { sent: true, recipient: input.recipient };
}

