import type { Tools } from "../generated/tools";

export default async function flow(
  input: { releaseNote: string; onCallEmail: string },
  tools: Tools
) {
  let sent = false;

  try {
    await tools.slack.send({
      channel: "#releases",
      message: input.releaseNote,
    });
    sent = true;
  } catch (error) {
    await tools.email.send({
      to: input.onCallEmail,
      subject: "Release note delivery failed",
      body: `Could not post the release note to #releases: ${String(error)}`,
    });
  }

  await tools.slack.send({
    channel: "#audit",
    message: `Audit: release note ${sent ? "delivered" : "NOT delivered"} to #releases.`,
  });

  return { sent };
}

import type { Tools } from "../generated/tools";

export default async function flow(
  input: { releaseNote: string; onCallAddress: string },
  tools: Tools
) {
  let delivered = false;

  try {
    await tools.slack.send({
      channel: "#releases",
      message: input.releaseNote,
    });
    delivered = true;
  } catch (error) {
    await tools.email.send({
      to: input.onCallAddress,
      subject: "Release note delivery failed",
      body: `Posting the release note to #releases failed: ${String(error)}`,
    });
  }

  const auditLine = delivered
    ? "Release note was posted to #releases."
    : "Release note did NOT go out to #releases; on-call has been alerted.";

  await tools.slack.send({
    channel: "#audit",
    message: auditLine,
  });

  return { delivered };
}

import type { Tools } from "../generated/tools";

export default async function flow(
  input: { repository: string },
  tools: Tools
) {
  const prs = await tools.github.getNewPRs({ repo: input.repository });

  let commentsPosted = 0;

  for (const pr of prs) {
    if (commentsPosted >= 5) {
      break;
    }

    if (pr.title.startsWith("WIP")) {
      continue;
    }

    await tools.github.addComment({
      pr,
      body: `This pull request is queued for review: ${pr.title}`,
    });

    commentsPosted += 1;
  }

  return { commentsPosted };
}

import type { Tools } from "../generated/tools";

function isWorkInProgress(pr: PullRequest): boolean {
  return pr.title.startsWith("WIP");
}

export default async function flow(
  input: { repository: string },
  tools: Tools
) {
  const prs = await tools.github.getNewPRs({ repo: input.repository });

  let commentsPosted = 0;

  for (const pr of prs) {
    if (commentsPosted >= 5) {
      break;
    }

    if (isWorkInProgress(pr)) {
      continue;
    }

    await tools.github.addComment({
      pr,
      body: `${pr.title} is queued for review.`
    });

    commentsPosted += 1;
  }

  return { commentsPosted };
}
